    def test_cap_reached_exactly(self):
        self.assertTrue(approve(5000, "clerk", 10000))
        self.assertFalse(approve(5000, "clerk", 10001))

    def test_errors(self):
        for a in (0, -1, -5000):
            with self.assertRaises(ValueError):
